     1	﻿<#
     2	  goat-usage.ps1 — Command Code GOAT 套餐额度看板（5 小时 / 周 / 月）
     3	  ------------------------------------------------------------------
     4	  数据来源：api.commandcode.ai 的 alpha 端点（用 keys.json 里的 user_ key 直连认证）
     5	
     6	    GET /alpha/billing/credits   -> windowLimits.fiveHour / weekly {used, cap, resetAt, exceeded}
     7	                                    credits.monthlyCredits = 本月剩余额度
     8	    GET /alpha/usage/summary     -> 当前计费周期已用额度（totalCredits）
     9	
    10	  月度上限 = 本周期已用 + 本月剩余（实测两账号均 ≈ 70）
    11	
    12	  用法：
    13	    .\goat-usage.ps1                 # 双账号一览
    14	    .\goat-usage.ps1 -Key 163        # 只看某个账号
    15	    .\goat-usage.ps1 -Watch 30       # 每 30 秒刷新（Ctrl+C 退出）
    16	    .\goat-usage.ps1 -Json           # 输出 JSON（给状态栏/宠物等外部消费）
    17	    .\goat-usage.ps1 -NoColor        # 纯文本
    18	#>
    19	[CmdletBinding()]
    20	param(
    21	  [string]$Key,
    22	  [int]$Watch = 0,
    23	  [switch]$Json,
    24	  [switch]$Brief,
    25	  [switch]$NoColor,
    26	  [int]$CacheSeconds = 60,
    27	  [switch]$Force,
    28	  [string]$KeysFile,
    29	  [string]$CacheFile
    30	)
    31	if (-not $KeysFile) { $KeysFile = Join-Path $PSScriptRoot 'keys.json' }
    32	
    33	$ErrorActionPreference = 'Stop'
    34	try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
    35	$Api = 'https://api.commandcode.ai'
    36	
    37	function Get-Usage([string]$bearer) {
    38	  $h = @{ Authorization = "Bearer $bearer" }
    39	  $credits = Invoke-RestMethod -Uri "$Api/alpha/billing/credits" -Headers $h -TimeoutSec 25 -UseBasicParsing
    40	  $summary = Invoke-RestMethod -Uri "$Api/alpha/usage/summary" -Headers $h -TimeoutSec 25 -UseBasicParsing
    41	  [pscustomobject]@{
    42	    fiveHour  = $credits.windowLimits.fiveHour
    43	    weekly    = $credits.windowLimits.weekly
    44	    monthUsed = [double]$summary.totalCredits
    45	    monthLeft = [double]$credits.credits.monthlyCredits
    46	    monthCap  = [double]$summary.totalCredits + [double]$credits.credits.monthlyCredits
    47	    requests  = $summary.totalCount
    48	    tokens    = $summary.totalTokens
    49	    exceeded  = $credits.windowLimits.exceeded
    50	  }
    51	}
    52	
    53	function Write-Bar([double]$used, [double]$cap, [int]$width = 30) {
    54	  $f = if ($cap -le 0) { 0 } else { [math]::Min(1.0, $used / $cap) }
    55	  $filled = [int][math]::Round($f * $width)
    56	  ('#' * $filled) + ('.' * ($width - $filled))
    57	}
    58	
    59	function Format-Reset($epochMs) {
    60	  $t = [DateTimeOffset]::FromUnixTimeMilliseconds([int64]$epochMs).LocalDateTime
    61	  $d = $t - (Get-Date)
    62	  if ($d.TotalSeconds -le 0) { return "$($t.ToString('MM-dd HH:mm')) (已重置)" }
    63	  if ($d.TotalDays -ge 1) { return ('{0:MM-dd HH:mm}（还有 {1} 天 {2} 小时）' -f $t, [int]$d.TotalDays, $d.Hours) }
    64	  if ($d.TotalHours -ge 1) { return ('{0:HH:mm}（还有 {1} 小时 {2} 分）' -f $t, [int]$d.TotalHours, $d.Minutes) }
    65	  return ('{0:HH:mm}（还有 {1} 分钟）' -f $t, [int]$d.TotalMinutes)
    66	}
    67	
    68	function Get-Color([double]$used, [double]$cap) {
    69	  if ($NoColor) { return 'Gray' }
    70	  $f = if ($cap -le 0) { 0 } else { $used / $cap }
    71	  if ($f -ge 0.9) { return 'Red' } elseif ($f -ge 0.7) { return 'Yellow' } else { return 'Green' }
    72	}
    73	
    74	function Render {
    75	  $cacheFile = if ($CacheFile) { $CacheFile } else { Join-Path $env:TEMP 'goat-usage-cache.json' }
    76	  $cached = $null
    77	  if (-not $Force -and $Watch -eq 0 -and $CacheSeconds -gt 0 -and (Test-Path $cacheFile)) {
    78	    try {
    79	      $c = Get-Content $cacheFile -Raw | ConvertFrom-Json
