    81	    } catch {}
    82	  }
    83	
    84	  $all = Get-Content $KeysFile -Raw | ConvertFrom-Json
    85	  $list = $all.keys | Where-Object { $_.enabled -ne $false }
    86	  if ($Key) { $list = $list | Where-Object { $_.name -eq $Key } }
    87	  if (-not $list) { throw "keys.json 里找不到账号 '$Key'" }
    88	
    89	  if ($cached) {
    90	    $rows = @($cached | Where-Object { -not $Key -or $_.name -eq $Key })
    91	  } else {
    92	  $rows = @()
    93	  foreach ($k in $list) {
    94	    try {
    95	      $u = Get-Usage $k.key
    96	      $rows += [pscustomobject]@{
    97	        name = $k.name; error = $null; plan = 'individual-goat'
    98	        fiveHourUsed = $u.fiveHour.used; fiveHourCap = $u.fiveHour.cap; fiveHourReset = $u.fiveHour.resetAt; fiveHourExceeded = $u.fiveHour.exceeded
    99	        weeklyUsed = $u.weekly.used; weeklyCap = $u.weekly.cap; weeklyReset = $u.weekly.resetAt; weeklyExceeded = $u.weekly.exceeded
   100	        monthUsed = $u.monthUsed; monthLeft = $u.monthLeft; monthCap = $u.monthCap
   101	        requests = $u.requests; tokens = $u.tokens
   102	        fetchedAt = (Get-Date).ToString('s')
   103	      }
   104	    } catch {
   105	      $rows += [pscustomobject]@{ name = $k.name; error = $_.Exception.Message; fetchedAt = (Get-Date).ToString('s') }
   106	    }
   107	  }
   108	try {
   109	    $tmpCache = "$cacheFile.tmp-$PID"
   110	    [IO.File]::WriteAllText($tmpCache, (@{ ts = (Get-Date).ToString('s'); rows = $rows } | ConvertTo-Json -Depth 6), [Text.UTF8Encoding]::new($false))
   111	    Move-Item -LiteralPath $tmpCache -Destination $cacheFile -Force
   112	  } catch {}
   113	  }
   114	
   115	  if ($Json) { return ($rows | ConvertTo-Json -Depth 6) }
   116	
   117	  if ($Brief) {
   118	    $parts = foreach ($r in $rows) {
   119	      if ($r.error) { "[$($r.name)] 查询失败"; continue }
   120	      $p5 = [math]::Round(100 * $r.fiveHourUsed / $r.fiveHourCap)
   121	      $pw = [math]::Round(100 * $r.weeklyUsed / $r.weeklyCap)
   122	      $pm = [math]::Round(100 * $r.monthUsed / $r.monthCap)
   123	      "[$($r.name)] 5h $p5% · 周 $pw% · 月 $pm%（月剩 $([math]::Round($r.monthLeft,1)))"
   124	    }
   125	    return ($parts -join '    ')
   126	  }
   127	
   128	  $out = @()
   129	  $out += "Command Code GOAT 额度 — $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
   130	  foreach ($r in $rows) {
   131	    $out += ''
   132	    if ($r.error) { $out += "[$($r.name)] 查询失败: $($r.error)"; continue }
   133	    $out += "[$($r.name)]  $($r.plan)"
   134	    foreach ($w in @(
   135	        @{ n = '5小时'; used = $r.fiveHourUsed; cap = $r.fiveHourCap; reset = $r.fiveHourReset; ex = $r.fiveHourExceeded },
   136	        @{ n = '本周 '; used = $r.weeklyUsed; cap = $r.weeklyCap; reset = $r.weeklyReset; ex = $r.weeklyExceeded },
   137	        @{ n = '本月 '; used = $r.monthUsed; cap = $r.monthCap; reset = $null; ex = $null }
   138	      )) {
   139	      $pct = if ($w.cap -le 0) { 0 } else { [math]::Round(100 * $w.used / $w.cap, 1) }
   140	      $line = '  {0} [{1}] {2,5}%  {3,7:N2} / {4,-7:N2}' -f $w.n, (Write-Bar $w.used $w.cap), $pct, $w.used, $w.cap
   141	      if ($w.reset) { $line += '  重置 ' + (Format-Reset $w.reset) }
   142	      if ($w.n -eq '本月 ') { $line += ('  剩余 {0:N2}' -f $r.monthLeft) }
   143	      if ($w.ex) { $line += '  [已超限]' }
   144	      $out += $line
   145	    }
   146	    $out += ('  本周期合计 {0} 次请求 / {1:N0} tokens' -f $r.requests, $r.tokens)
   147	  }
   148	  $out
   149	}
   150	
   151	if ($Watch -gt 0) {
   152	  while ($true) {
   153	    Clear-Host
   154	    Render | ForEach-Object { Write-Host $_ }
   155	    Write-Host ''
   156	    Write-Host "每 $Watch 秒刷新，Ctrl+C 退出" -ForegroundColor DarkGray
   157	    Start-Sleep -Seconds $Watch
   158	  }
   159	} else {
   160	  Render
   161	}
