     1	#!/usr/bin/env node
     2	/**
     3	 * quota-http.mjs -- local quota HTTP endpoint for UI panels (dsh web / Reasonix status bar).
     4	 *   GET /quota          -> { ok, ts, rows: [...] }            (JSON, for UI panels)
     5	 *   GET /balance        -> plain text one-liner (6 numbers)   (for Reasonix balance_url)
     6	 *   GET /balance?format=json -> { is_available, balance_infos: [...] }
     7	 *   GET /health         -> { ok: true }
     8	 * Data source: goat-usage.ps1 (account metadata; querying costs no quota).
     9	 */
    10	import http from 'node:http';
    11	import os from 'node:os';
    12	import path from 'node:path';
    13	import { execFileSync } from 'node:child_process';
    14	import fs from 'node:fs';
    15	
    16	const PORT = Number(process.env.QUOTA_HTTP_PORT || 8790);
    17	const SCRIPT = process.env.GOAT_USAGE_SCRIPT || 'D:\\Toolbox\\goat-gateway\\goat-usage.ps1';
    18	const CACHE = path.join(os.tmpdir(), 'goat-quota-http-cache.json');
    19	const TTL_MS = 10000;
    20	const HITLOG = 'D:\\Toolbox\\goat-gateway\\logs\\balance-hits.log';
    21	
    22	let last = { at: 0, body: null };
    23	
    24	function run(extra) {
    25	  const args = ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', SCRIPT, '-Json',
    26	    '-CacheSeconds', '10', '-CacheFile', CACHE].concat(extra || []);
    27	  return execFileSync('powershell', args, { encoding: 'utf8', timeout: 90000, windowsHide: true, maxBuffer: 4 * 1024 * 1024 });
    28	}
    29	
    30	function readQuota(force) {
    31	  const now = Date.now();
    32	  if (!force && last.body && now - last.at < TTL_MS) { return last.body; }
