    34	  try { parsed = JSON.parse(run(force ? ['-Force'] : [])); }
    35	  catch { parsed = JSON.parse(run(['-Force'])); }
    36	  const body = { ok: true, ts: new Date().toISOString(), rows: Array.isArray(parsed) ? parsed : [parsed] };
    37	  last = { at: now, body };
    38	  return body;
    39	}
    40	
    41	const pct = (u, c) => (Number(c) > 0 ? Math.round((100 * Number(u)) / Number(c)) : 0);
