    43	
    44	const server = http.createServer((req, res) => {
    45	  const url = new URL(req.url, 'http://127.0.0.1:' + PORT);
    46	  const cors = {
    47	    'Access-Control-Allow-Origin': '*',
    48	    'Access-Control-Allow-Methods': 'GET,OPTIONS',
    49	    'Access-Control-Allow-Headers': '*',
    50	    'Cache-Control': 'no-store'
    51	  };
    52	  if (req.method === 'OPTIONS') { res.writeHead(204, cors); res.end(); return; }
    53	  if (url.pathname === '/health') {
    54	    res.writeHead(200, Object.assign({ 'Content-Type': 'application/json' }, cors));
    55	    res.end(JSON.stringify({ ok: true }));
    56	    return;
    57	  }
    58	  if (url.pathname === '/quota') {
    59	    try {
    60	      const body = readQuota(url.searchParams.get('force') === '1');
    61	      res.writeHead(200, Object.assign({ 'Content-Type': 'application/json; charset=utf-8' }, cors));
    62	      res.end(JSON.stringify(body));
    63	    } catch (e) {
    64	      res.writeHead(500, Object.assign({ 'Content-Type': 'application/json; charset=utf-8' }, cors));
    65	      res.end(JSON.stringify({ ok: false, error: String((e && e.message) || e) }));
    66	    }
    67	    return;
    68	  }
