    94	        res.writeHead(200, Object.assign({ 'Content-Type': 'application/json; charset=utf-8' }, cors));
    95	        res.end(JSON.stringify({ is_available: true, balance_infos: infos }));
    96	        return;
    97	      }
    98	      const line = rows.map((r) => r.error
    99	        ? r.name + ' error'
   100	        : r.name + ' 5h ' + pct(r.fiveHourUsed, r.fiveHourCap) + '% '
   101	          + lbl.weekly + ' ' + pct(r.weeklyUsed, r.weeklyCap) + '% '
   102	          + lbl.monthly + ' ' + pct(r.monthUsed, r.monthCap) + '%').join('   |   ');
   103	      res.writeHead(200, Object.assign({ 'Content-Type': 'text/plain; charset=utf-8' }, cors));
   104	      res.end(line);
   105	    } catch (e) {
   106	      res.writeHead(500, Object.assign({ 'Content-Type': 'text/plain; charset=utf-8' }, cors));
   107	      res.end('quota error');
   108	    }
   109	    return;
   110	  }
   111	  res.writeHead(404, cors); res.end();
   112	});
